package com.inventario.controller;
import com.inventario.domain.Producto; import com.inventario.dto.Dtos.*; import com.inventario.service.ProductoService; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/productos") @CrossOrigin
public class ProductoController { private final ProductoService service; public ProductoController(ProductoService service){this.service=service;} @GetMapping public List<Producto> listar(){return service.listar();} @GetMapping("/catalogo") public List<Producto> catalogo(){return service.catalogo();} @PostMapping public Producto crear(@RequestBody ProductoRequest r){return service.crear(r);} @PutMapping("/{id}") public Producto actualizar(@PathVariable Long id,@RequestBody ProductoRequest r){return service.actualizar(id,r);} @DeleteMapping("/{id}") public void eliminar(@PathVariable Long id){service.eliminar(id);} }
